4. Calculate the SHA-256 hash of the SHA-256 hash of the Account ID; take the first 4 bytes. This value is the "checksum".

const address type prefix = Buffer.from([0x00]); const payload = Buffer.concat([address type prefix, account id]); const chksum hash1 = crypto.createHash('sha256').update(payload).digest(); const chksum hash2 = crypto.createHash('sha256').update(chksum hash1).digest(); const checksum = chksum hash2.slice(0,4);

5. Concatenate the payload and the checksum. Calculate the base58 value of the concatenated buffer. The result is the address.

const dataToEncode = Buffer.concat([payload, checksum]); const address = base58.encode(dataToEncode); console.log(address); // rDTXLQ7ZKZVKz33zJbHjgVShjsBnqMBhmN

.xrp-benefits-grid {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: 1px;
 background: 343437;
 border: 1px solid 343437;
 border-radius: 8px;
 overflow: hidden;
 margin: 1.5rem 0;
}
.xrp-benefits-grid .cell {
 display: flex;
 flex-direction: column;
 align-items: center;
 gap: 10px;
 padding: 28px 16px;
 background: 232325;
}
.xrp-benefits-grid .ti {
 font-size: 28px;
 color: 21E46B;
}
.xrp-benefits-grid span {
 font-size: 11px;
 color: C1C1C2;
 text-align: center;
 line-height: 1.4;
 font-family: 'Inter', 'Helvetica Neue', sans-serif;
}
/ Light theme: lighten the cells and darken the text/icons for contrast. /
html.light .xrp-benefits-grid,
html.light .xrp-benefits-grid .cell { background: F0F3F7; }
html.light .xrp-benefits-grid { background: CAD4DF; border-color: CAD4DF; }
html.light .xrp-benefits-grid .ti { color: 1E8A50; }
html.light .xrp-benefits-grid span { color: 72777E; }
/ Drop to 3 columns on narrow screens so the grid fits on mobile. /
@media screen and (max-width: 500px) {
 .xrp-benefits-grid {
 grid-template-columns: repeat(3, 1fr);
 }
}

